import React, { useState } from 'react';

function AddTrip({ setTrips }) {
    const [tripName, setTripName] = useState('');
    const [numMembers, setNumMembers] = useState(0);
    const [familyMembers, setFamilyMembers] = useState([]);

    // Update number of member input fields
    const handleNumMembersChange = (e) => {
        const count = parseInt(e.target.value) || 0;
        setNumMembers(count);
        setFamilyMembers(Array(count).fill(''));
    };

    // Update name in a specific input
    const handleMemberNameChange = (index, value) => {
        const updatedMembers = [...familyMembers];
        updatedMembers[index] = value;
        setFamilyMembers(updatedMembers);
    };

    const handleAddTrip = (e) => {
        e.preventDefault();
        console.log('Trip added:', { tripName, familyMembers });
        // Add to parent state if needed:
        // setTrips((prev) => [...prev, { tripName, familyMembers }]);
    };

    return (
        <div>
            <h2>Add New Trip</h2>
            <form onSubmit={handleAddTrip}>
                <div>
                    <label>Trip Name:</label><br />
                    <input
                        type="text"
                        value={tripName}
                        onChange={(e) => setTripName(e.target.value)}
                        required
                    />
                </div>

                <div>
                    <label>Number of Family Members:</label><br />
                    <input
                        type="number"
                        min="0"
                        value={numMembers}
                        onChange={handleNumMembersChange}
                        required
                    />
                </div>

                <div>
                    <label>Family Members:</label><br />
                    {familyMembers.map((name, index) => (
                        <div key={index}>
                            <input
                                type="text"
                                placeholder={`Member ${index + 1} Name`}
                                value={name}
                                onChange={(e) =>
                                    handleMemberNameChange(index, e.target.value)
                                }
                                required
                            />
                        </div>
                    ))}
                </div>

                <button type="submit">Add Trip</button>
            </form>
        </div>
    );
}

export default AddTrip;
